{
  var panel = $('#CosmeticsPanel');
  if (panel.visible)
    panel.visible = false;
  else
    panel.visible = true;
}

function CloseCosmetics()
{
  var panel = $('#CosmeticsPanel');
  panel.visible = false;
}

